	trials_total: number;
	trials_counted: number;
	asof_violations: number;
	gate_sha256: string;
	result_hash: string;
	features: ScreenFeature[];
}

export interface ScreenSummary {
	id: string;
	market: string;
	title: string;
	state: ScreenDoc["state"];
	hypothesis: string;
	sealedAt: string;
	unit: "D" | "H";
	candidates: number;
