	title={doc.title}
	titleMenu="experiments"
	note={doc.hypothesis}
	facts={[
		stepFact,
		{ icon: LockIcon, label: `봉인 ${doc.sealed_at || "전"}`, tip: sealTip },
		{
			icon: HashIcon,
			label: doc.gate_sha256.slice(0, 8),
			tip: `이 지문 칩은 합격선 파일의 sha256 ${doc.gate_sha256}과 결과 지문 ${doc.result_hash}다.`,
		},
