					flow={doc.gate_flow}
					entrants={doc.features.map((f) => f.code)}
					finish="채택"
					onselect={pick}
				/>
			</div>
			<div class="research-table" data-role="candidate-table">
				<Table.Root>
					<Table.Header>
						<Table.Row>
							<Table.Head class="h-[50px]">후보</Table.Head>
							<Table.Head class="h-[50px]">원천·변환</Table.Head>

