edits.newText:
export function pctOf(v: number | null | undefined, digits = 1): string {
	if (v == null || !Number.isFinite(v)) return "—";
	const s = (v * 100).toFixed(digits);
	return v > 0 ? `+${s}%` : `${s.replace("-", "−")}%`;
}

/** A round tick step (1, 2 or 5 × a power of ten) for a value range. */
function tickStep(range: number): number {
	if (!Number.isFinite(range) || range <= 0) return 1;
	const raw = range / 5;
	const mag = 10 ** Math.floor(Math.log10(raw));
	const norm = raw / mag;
	const nice = norm < 1.5 ? 1 : norm < 3 ? 2 : norm < 7 ? 5 : 10;
	return nice * mag;
}

/** Round axis ticks covering [min, max] (and zero when the range straddles it). */
export function niceTicks(min: number, max: number): number[] {
	if (!Number.isFinite(min) || !Number.isFinite(max)) return [0];
	if (min > max) [min, max] = [max, min];
	const step = tickStep(max - min);
	const lo = Math.ceil(min / step - 1e-9) * step;
	const hi = Math.floor(max / step + 1e-9) * step;
	const out: number[] = [];
	for (let v = lo; v <= hi + step * 1e-9; v += step) {
		// Strip binary floating-point noise so labels stay round.
		out.push(Number((Math.round(v / step) * step).toPrecision(12)));
	}
	if (out.length === 0) out.push(0);
	return out;
}

/** A UTC date as `YYYY.MM.DD`; dots keep day 01 from reading as a January tick. */
export function dateLabel(t: number): string {
	const d = new Date(t);
	const y = d.getUTCFullYear();
	const m = String(d.getUTCMonth() + 1).padStart(2, "0");
	const day = String(d.getUTCDate()).padStart(2, "0");
	return `${y}.${m}.${day}`;
}

