	return v > 0 ? `+${s}%` : `${s.replace("-", "−")}%`;
}

/** A round tick step (1, 2 or 5 × a power of ten) for a value range. */
function tickStep(range: number): number {
	if (!Number.isFinite(range) || range <= 0) return 1;
	const raw = range / 5;
	const mag = 10 ** Math.floor(Math.log10(raw));
	const norm = raw / mag;
	const nice = norm < 1.5 ? 1 : norm < 3 ? 2 : norm < 7 ? 5 : 10;
	return nice * mag;
}

/** Round axis ticks covering [min, max] (and zero when the range straddles it). */
export function niceTicks(min: number, max: number): number[] {
	if (!Number.isFinite(min) || !Number.isFinite(max)) return [0];
	if (min > max) [min, max] = [max, min];
	const step = tickStep(max - min);
	const lo = Math.ceil(min / step - 1e-9) * step;
	const hi = Math.floor(max / step + 1e-9) * step;
	const out: number[] = [];
	for (let v = lo; v <= hi + step * 1e-9; v += step) {
		// Strip binary floating-point noise so labels stay round.
		out.push(Number((Math.round(v / step) * step).toPrecision(12)));
	}
	if (out.length === 0) out.push(0);
	return out;
}

/** A UTC date as `YYYY.MM.DD`; dots keep day 01 from reading as a January tick. */
export function dateLabel(t: number): string {
	const d = new Date(t);
	const y = d.getUTCFullYear();
	const m = String(d.getUTCMonth() + 1).padStart(2, "0");
	const day = String(d.getUTCDate()).padStart(2, "0");
	return `${y}.${m}.${day}`;
}

export interface ScreenCurveView {
	t: number[];
	rule: number[];
	hold: number[];
	ticks: number[];
	labels: string[];
}

/** Scale fraction sums to percent, carry a missing point forward, and add axis ticks. */
export function curveView(trial: ScreenTrial | null | undefined): ScreenCurveView | null {
	const curve = trial?.curve;
	if (!curve || !curve.t || curve.t.length < 2) return null;
	const carry = (src: (number | null)[] | undefined): number[] => {
		let prev = 0;
		return curve.t.map((_, i) => {
			const v = src?.[i];
			if (v != null && Number.isFinite(v)) prev = v;
			return prev * 100;
		});
	};
	const rule = carry(curve.rule);
	const hold = carry(curve.hold);
	const values = [...rule, ...hold];
	return {
		t: [...curve.t],
		rule,
		hold,
		ticks: niceTicks(Math.min(...values), Math.max(...values)),
		labels: curve.t.map(dateLabel),
	};
}

/** The trial at a horizon, falling back to the feature's lead trial. */
export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
	if (h !== "lead") {
		const found = f.trials.find((t) => t.h === h);
		if (found) return found;
	}
	return leadTrial(f);
}

export interface ScreenRuleTile {
	id: string;
	group: "entry" | "fill" | "exit" | "gate";
	name: string;
	label: string;
	tip: string;
}

/** Entry/fill/exit tiles describing the rule the document was screened with. */
export function screenRule(doc: ScreenDoc, feature: ScreenFeature, trial: ScreenTrial): ScreenRuleTile[] {
	const fixed = doc.fixed_sign != null && Number.isFinite(doc.fixed_sign) ? doc.fixed_sign : null;
	const signs = trial.folds.map((x) => x.train_sign).filter((x) => x !== 0);
	const signChanged = new Set(signs).size > 1;
	const sign = fixed ?? (signs.length ? signs[signs.length - 1] : trial.train_sign) ?? 1;
	const long = sign >= 0;
	const direction = fixed != null
		? {
				name: long ? "기준 위면 롱" : "기준 위면 숏",
				label: "순방향",
				tip: `학습 방향을 ${fixed > 0 ? "+" : "−"}${Math.abs(fixed)}로 고정했다. 지표가 기준 위면 ${long ? "사고" : "판다"}.`,
			}
		: {
				name: long ? "기준 위면 롱" : "기준 위면 숏",
				label: signChanged ? "부호 바뀜" : long ? "순방향" : "역추세",
				tip: signChanged
					? "시험 연도마다 학습 방향의 부호가 달라 한 방향으로 읽을 수 없다."
					: `학습 때 정한 방향(${long ? "+" : "−"})을 그대로 따른다.`,
			};
	const cost = `${(doc.cost_per_side * 1e4).toFixed(0)}bp`;
	const unit = doc.unit === "H" ? "시간" : "일";
	const tiles: ScreenRuleTile[] = [
		{
			id: "indicator",
			group: "entry",
			name: featureName(feature),
			label: feature.tradeable === false ? "참고 지표" : "후보 지표",
			tip: featureDef(feature),
		},
		{ id: "direction", group: "entry", ...direction },
		{
			id: "fill",
			group: "fill",
			name: `편도 ${cost}`,
			label: "비용",
			tip: `편도 ${cost}를 적용했다. 왕복으로는 ${(doc.cost_per_side * 2e4).toFixed(0)}bp다.`,
		},
		{
			id: "hold",
			group: "exit",
			name: `${trial.h}${doc.unit} 보유`,
			label: `${trial.h}${unit}`,
			tip: `진입 뒤 ${trial.h}${unit} 동안 보유한다.`,
		},
	];
	if (doc.regime === "down") {
		tiles.push({
			id: "regime",
			group: "gate",
			name: "하락장만",
			label: "국면 게이트",
			tip: "종가가 200일 평균 아래인 날만 점수를 매기고 매매한다.",
		});
	}
	return tiles;
}

